-- An activity belongs to exactly one lead, client or matter.
ALTER TABLE "activities" DROP CONSTRAINT "activities_one_subject";
ALTER TABLE "activities" ADD CONSTRAINT "activities_one_subject"
  CHECK (num_nonnulls("lead_id", "client_id", "matter_id") = 1);

-- A participant is exactly one of: client, directory professional, partner organization.
ALTER TABLE "matter_participants" ADD CONSTRAINT "matter_participants_one_party"
  CHECK (num_nonnulls("client_id", "professional_id", "partner_org_id") = 1);

-- A task is linked to at most one record.
ALTER TABLE "tasks" ADD CONSTRAINT "tasks_one_link"
  CHECK (num_nonnulls("matter_id", "client_id", "lead_id") <= 1);

-- One active assignment per person per matter.
CREATE UNIQUE INDEX "matter_assignments_active_key" ON "matter_assignments" ("matter_id", "membership_id")
  WHERE "unassigned_at" IS NULL;

-- Matter type names are unique per agency regardless of letter case.
CREATE UNIQUE INDEX "matter_types_tenant_lower_name_key" ON "matter_types" ("tenant_id", lower("name"));

-- Row-Level Security: every Stage 5 table is visible and writable only inside the active tenant.
DO $$
DECLARE t TEXT;
BEGIN
  FOREACH t IN ARRAY ARRAY[
    'matter_types', 'matter_stages', 'checklist_template_items', 'matters', 'matter_assignments',
    'matter_participants', 'matter_deadlines', 'checklist_items', 'matter_status_history', 'tasks'
  ] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format(
      'CREATE POLICY %I ON %I USING (tenant_id = app_setting_uuid(''app.tenant_id'')) WITH CHECK (tenant_id = app_setting_uuid(''app.tenant_id''))',
      t || '_isolation', t);
  END LOOP;
END $$;

-- Status history is append-only for the API runtime user (when that role exists).
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'crm_app') THEN
    REVOKE UPDATE, DELETE ON "matter_status_history" FROM crm_app;
  END IF;
END $$;

-- Defaults for existing workspaces. Keep in sync with packages/contracts/src/reference-defaults.ts
-- and packages/contracts/src/matter-defaults.ts (DEC-13: generic editable examples, no legal rules).
DO $$
DECLARE t RECORD; mt RECORD;
BEGIN
  FOR t IN SELECT id FROM "tenants" LOOP
    PERFORM set_config('app.tenant_id', t.id::text, true);
    INSERT INTO "reference_options" ("id", "tenant_id", "category", "key", "name", "sort_order", "updated_at")
    SELECT gen_random_uuid(), t.id, 'PARTICIPANT_ROLE'::"ReferenceCategory", d.key, d.name, d.sort_order, now()
    FROM (VALUES
      ('dependant', 'Dependant', 1),
      ('sponsor', 'Sponsor', 2),
      ('employer', 'Employer', 3),
      ('external_lawyer', 'External legal consultant', 4),
      ('accountant', 'CA / Accountant', 5),
      ('referral_partner', 'Referral partner', 6),
      ('other', 'Other', 99)
    ) AS d(key, name, sort_order)
    ON CONFLICT ("tenant_id", "category", "key") DO NOTHING;

    IF NOT EXISTS (SELECT 1 FROM "matter_types" WHERE "tenant_id" = t.id) THEN
      FOR mt IN SELECT * FROM (VALUES
        ('Student', 1), ('Skilled', 2), ('Partner', 3), ('Employer-sponsored', 4)
      ) AS x(name, sort_order) LOOP
        WITH new_type AS (
          INSERT INTO "matter_types" ("id", "tenant_id", "name", "sort_order", "updated_at")
          VALUES (gen_random_uuid(), t.id, mt.name, mt.sort_order, now())
          RETURNING "id"
        )
        INSERT INTO "matter_stages" ("id", "tenant_id", "matter_type_id", "name", "sort_order", "is_terminal")
        SELECT gen_random_uuid(), t.id, new_type.id, s.name, s.sort_order, s.is_terminal
        FROM new_type, (VALUES
          ('Intake', 1, false),
          ('Collecting documents', 2, false),
          ('Preparing application', 3, false),
          ('Lodged', 4, false),
          ('Decision received', 5, true)
        ) AS s(name, sort_order, is_terminal);
      END LOOP;
    END IF;
  END LOOP;
  PERFORM set_config('app.tenant_id', '', true);
END $$;
